"use client";

import { useMemo, useRef, type RefObject } from "react";
import {
  motion,
  useScroll,
  useTransform,
  useMotionTemplate,
  type MotionValue,
} from "motion/react";
import { cn } from "@/lib/utils";

export interface LumenProps {
  text?: string;
  className?: string;
  dimOpacity?: number;
  fadeSpan?: number;
  blurAmount?: number;
  startOffset?: number;
  endOffset?: number;
  highlightColor?: string;
  scrollContainerRef?: RefObject<HTMLElement | null>;
  reducedMotion?: boolean;
}

interface WordProps {
  word: string;
  progress: MotionValue<number>;
  start: number;
  end: number;
  dimOpacity: number;
  blurAmount: number;
  highlightColor: string;
  still: boolean;
}

function Word({
  word,
  progress,
  start,
  end,
  dimOpacity,
  blurAmount,
  highlightColor,
  still,
}: WordProps) {
  const opacity = useTransform(progress, [start, end], [dimOpacity, 1], {
    clamp: true,
  });
  const blurPx = useTransform(progress, [start, end], [blurAmount, 0], {
    clamp: true,
  });
  const filter = useMotionTemplate`blur(${blurPx}px)`;

  const glow = useTransform(
    progress,
    [start, (start + end) / 2, end],
    [0, 1, 0],
    { clamp: true },
  );
  const glowPx = useTransform(glow, (g) => g * 12);
  const textShadow = useMotionTemplate`0 0 ${glowPx}px ${highlightColor}`;

  if (still) return <span className="mr-[0.25em] inline-block">{word}</span>;

  return (
    <motion.span
      className="mr-[0.25em] inline-block will-change-[opacity,filter]"
      style={{ opacity, filter, textShadow }}
    >
      {word}
    </motion.span>
  );
}

export default function Lumen({
  text = "",
  className,
  dimOpacity = 0.15,
  fadeSpan = 6,
  blurAmount = 4,
  startOffset = 0.15,
  endOffset = 0.6,
  highlightColor = "#a855f7",
  scrollContainerRef,
  reducedMotion = false,
}: LumenProps) {
  const targetRef = useRef<HTMLParagraphElement>(null);
  const words = useMemo(() => text.split(/\s+/).filter(Boolean), [text]);

  const { scrollYProgress } = useScroll({
    target: targetRef,
    ...(scrollContainerRef ? { container: scrollContainerRef } : {}),
    offset: ["start end", "end start"],
  });

  const lo = Math.min(startOffset, endOffset - 0.05);
  const progress = useTransform(scrollYProgress, [lo, endOffset], [0, 1], {
    clamp: true,
  });

  const total = words.length || 1;
  const span = Math.min(Math.max(fadeSpan, 1), total);

  return (
    <p ref={targetRef} className={cn("text-balance", className)}>
      {words.map((word, i) => (
        <Word
          key={`${word}-${i}`}
          word={word}
          progress={progress}
          start={i / total}
          end={Math.min(1, (i + span) / total)}
          dimOpacity={dimOpacity}
          blurAmount={blurAmount}
          highlightColor={highlightColor}
          still={reducedMotion}
        />
      ))}
    </p>
  );
}
